using Flowzy.Repository.Data;using Flowzy.Repository.Entities;using Flowzy.Service.Contracts;using Flowzy.Service.Exceptions;using Microsoft.EntityFrameworkCore;
namespace Flowzy.Service.Dashboard;
public sealed class DashboardService(FlowzyDbContext db):IDashboardService
{private static DateTime Now=>DateTime.UtcNow;
 public async Task<object>Get(string v,string? email,string? term,string? course,long? groupId,string? status,int page,int size,int limit,CancellationToken ct)=>v switch{
 "admin/groups"=>await Progress(await Groups().ToListAsync(ct),ct),"admin/projects"=>await Projects(await Groups().ToListAsync(ct),ct),"admin/mentors"=>await Mentors(ct),"admin/timeline"=>await Meetings(db.MentorMeetings,ct),"admin/execution-status"=>await Execution(ct),"admin/overview"=>await Overview(term,course,limit,ct),"tv-showcase/projects"=>await Tv(false,term,course,page,size,ct),"tv-showcase/recruitments"=>await Tv(true,term,course,page,size,ct),"mentor/groups"=>await Progress(await MentorGroups(email!,ct),ct),"mentor/meetings"=>await MentorMeetings(email!,status,ct),"student/groups"=>await Progress(await StudentGroups(email!,ct),ct),"student/progress"=>await StudentProgress(email!,ct),"student/projects"=>await Projects(await StudentGroups(email!,ct),ct),"instructor/milestones"=>await InstructorMilestones(email!,term,course,groupId,ct),"student/milestones"=>await StudentMilestones(email!,groupId??throw new BadRequestException("groupId is required"),ct),_=>throw new NotFoundException("Dashboard view not found")};
 private IQueryable<StudentGroup>Groups()=>db.StudentGroups.AsNoTracking().Include(x=>x.Mentor).ThenInclude(x=>x!.Account).Include(x=>x.Instructor).Include(x=>x.LeaderStudent).ThenInclude(x=>x!.Account).Include(x=>x.SelectedProblem).Include(x=>x.StudentGroupMembers).Include(x=>x.GroupRecruitmentNeeds).OrderByDescending(x=>x.UpdatedAt);
 private async Task<List<StudentGroup>>StudentGroups(string email,CancellationToken ct){var s=await db.Students.Include(x=>x.Account).FirstOrDefaultAsync(x=>x.Account.Email==email,ct)??throw new NotFoundException($"Student profile not found for email: {email}");return await Groups().Where(x=>x.StudentGroupMembers.Any(m=>m.StudentId==s.Id)).ToListAsync(ct);}
 private async Task<List<StudentGroup>>MentorGroups(string email,CancellationToken ct){var m=await db.Mentors.Include(x=>x.Account).FirstOrDefaultAsync(x=>x.Account.Email==email,ct)??throw new NotFoundException($"Mentor profile not found for email: {email}");return await Groups().Where(x=>x.MentorId==m.Id).ToListAsync(ct);}
 private async Task<object>Progress(List<StudentGroup> groups,CancellationToken ct){var ids=groups.Select(x=>x.Id).ToList();var tasks=await db.GroupTasks.AsNoTracking().Where(x=>ids.Contains(x.GroupId)).ToListAsync(ct);return groups.Select(g=>GroupProgress(g,tasks)).ToList();}
 private static object GroupProgress(StudentGroup g,List<GroupTask> all){var t=all.Where(x=>x.GroupId==g.Id&&x.ArchivedAt==null).ToList();var done=t.LongCount(x=>x.Status=="DONE");var ip=t.LongCount(x=>x.Status is "IN_PROGRESS"or"REVIEW");var overdue=t.LongCount(Overdue);return new{GroupId=g.Id,g.Term,g.CourseCode,g.GroupNo,GroupName=g.Name,g.ProjectName,Status=g.Status,MentorId=g.MentorId,MentorCode=g.Mentor?.MentorCode,MentorName=g.Mentor?.FullName,MemberCount=g.StudentGroupMembers.Count,TotalTasks=(long)t.Count,CompletedTasks=done,InProgressTasks=ip,OverdueTasks=overdue,ProgressPercent=Percent(done,t.Count),NextDueAt=t.Where(x=>x.DueAt!=null&&x.Status!="DONE").Min(x=>(DateTime?)x.DueAt),g.UpdatedAt};}
 private async Task<object>Projects(List<StudentGroup> groups,CancellationToken ct){var ids=groups.Select(x=>x.Id).ToList();var tasks=await db.GroupTasks.AsNoTracking().Where(x=>ids.Contains(x.GroupId)&&x.ArchivedAt==null).ToListAsync(ct);return groups.Select(g=>{var t=tasks.Where(x=>x.GroupId==g.Id).ToList();return new{GroupId=g.Id,g.Term,g.CourseCode,g.GroupNo,GroupName=g.Name,g.ProjectName,g.IdeaDescription,g.ResearchDomain,GroupStatus=g.Status,ProgressPercent=Percent(t.LongCount(x=>x.Status=="DONE"),t.Count)};}).ToList();}
 private async Task<object>Mentors(CancellationToken ct){return await db.Mentors.AsNoTracking().Include(x=>x.Account).Select(m=>new{MentorId=m.Id,m.MentorCode,MentorName=m.FullName,Email=m.Account.Email,AssignedGroupCount=db.StudentGroups.LongCount(g=>g.MentorId==m.Id),ScheduledMeetingCount=db.MentorMeetings.LongCount(x=>x.MentorId==m.Id&&x.Status=="SCHEDULED")}).ToListAsync(ct);}
 private async Task<object>Meetings(IQueryable<MentorMeeting> query,CancellationToken ct){return await query.AsNoTracking().Include(x=>x.Group).ThenInclude(x=>x.SelectedProblem).Include(x=>x.Mentor).OrderBy(x=>x.StartAt).Select(x=>new{x.Id,x.GroupId,GroupName=x.Group.Name,x.Group.GroupNo,x.Group.ProjectName,x.Group.SelectedProblemId,SelectedProblemTitle=x.Group.SelectedProblem==null?null:x.Group.SelectedProblem.Title,x.MentorId,x.Mentor.MentorCode,MentorName=x.Mentor.FullName,x.StartAt,x.EndAt,x.Status}).ToListAsync(ct);}
 private async Task<object>MentorMeetings(string email,string? status,CancellationToken ct){var m=await db.Mentors.Include(x=>x.Account).FirstOrDefaultAsync(x=>x.Account.Email==email,ct)??throw new NotFoundException($"Mentor profile not found for email: {email}");var q=db.MentorMeetings.Where(x=>x.MentorId==m.Id&&x.Group.MentorId==m.Id);if(!string.IsNullOrWhiteSpace(status)&&status.ToUpper()!="ALL")q=q.Where(x=>x.Status==status.ToUpper());return await Meetings(q,ct);}
 private async Task<object>Execution(CancellationToken ct){var groups=await Groups().ToListAsync(ct);var tasks=await db.GroupTasks.AsNoTracking().ToListAsync(ct);var meetings=await db.MentorMeetings.LongCountAsync(ct);var active=tasks.Where(x=>x.ArchivedAt==null).ToList();var done=active.LongCount(x=>x.Status=="DONE");var stats=new{TotalGroups=(long)groups.Count,TotalProjects=groups.LongCount(x=>!string.IsNullOrWhiteSpace(x.ProjectName)),TotalMentors=await db.Mentors.LongCountAsync(ct),TotalMeetings=meetings,TotalTasks=(long)active.Count,CompletedTasks=done,OverdueTasks=active.LongCount(Overdue),ProgressPercent=Percent(done,active.Count)};var gs=new Dictionary<string,long>{{"ACTIVE",groups.LongCount(x=>x.Status=="ACTIVE")},{"INACTIVE",groups.LongCount(x=>x.Status=="INACTIVE")}};var ts=new[]{"BACKLOG","TODO","IN_PROGRESS","REVIEW","DONE","BLOCKED"}.ToDictionary(x=>x,x=>active.LongCount(t=>t.Status==x));return new{Stats=stats,GroupStatusCounts=gs,TaskStatusCounts=ts,Groups=(IEnumerable<object>)groups.Select(g=>GroupProgress(g,tasks)).ToList()};}
 private async Task<object>StudentProgress(string email,CancellationToken ct){var groups=await StudentGroups(email,ct);var ids=groups.Select(x=>x.Id).ToList();var tasks=await db.GroupTasks.AsNoTracking().Where(x=>ids.Contains(x.GroupId)).ToListAsync(ct);var meetings=await db.MentorMeetings.LongCountAsync(x=>ids.Contains(x.GroupId),ct);var active=tasks.Where(x=>x.ArchivedAt==null).ToList();var done=active.LongCount(x=>x.Status=="DONE");var stats=new{TotalGroups=(long)groups.Count,TotalProjects=groups.LongCount(x=>!string.IsNullOrWhiteSpace(x.ProjectName)),TotalMentors=groups.Where(x=>x.MentorId!=null).Select(x=>x.MentorId).Distinct().LongCount(),TotalMeetings=meetings,TotalTasks=(long)active.Count,CompletedTasks=done,OverdueTasks=active.LongCount(Overdue),ProgressPercent=Percent(done,active.Count)};var names=groups.ToDictionary(x=>x.Id,x=>x.Name);var checks=active.Where(x=>x.DueAt!=null).OrderBy(x=>x.DueAt).Select(x=>new{TaskId=x.Id,x.GroupId,GroupName=names[x.GroupId],x.Title,x.Status,x.Priority,x.DueAt,Overdue=Overdue(x)});return new{Stats=stats,Groups=groups.Select(g=>GroupProgress(g,tasks)),Checkpoints=checks};}
 private async Task<object>InstructorMilestones(string email,string? term,string? course,long? gid,CancellationToken ct){var i=await db.Instructors.Include(x=>x.Account).FirstOrDefaultAsync(x=>x.Account.Email==email,ct)??throw new NotFoundException($"Instructor profile not found for email: {email}");var q=Groups().Where(x=>x.InstructorId==i.Id);if(!string.IsNullOrWhiteSpace(term))q=q.Where(x=>x.Term==term);if(!string.IsNullOrWhiteSpace(course))q=q.Where(x=>x.CourseCode==course);if(gid!=null)q=q.Where(x=>x.Id==gid);var groups=await q.ToListAsync(ct);if(gid!=null&&groups.Count==0)throw new NotFoundException("Group not found for this instructor scope");return await Milestones(groups,i.Id,term,course,ct);}
 private async Task<object>StudentMilestones(string email,long gid,CancellationToken ct){var groups=await StudentGroups(email,ct);var g=groups.FirstOrDefault(x=>x.Id==gid)??throw new ForbiddenException("You cannot view milestones for this group");return await Milestones([g],g.InstructorId,g.Term,g.CourseCode,ct);}
 private async Task<object>Milestones(List<StudentGroup> groups,long? iid,string? term,string? course,CancellationToken ct){if(iid is null||groups.Count==0)return Array.Empty<object>();var mq=db.CourseMilestones.AsNoTracking().Where(x=>x.InstructorId==iid&&x.Status!="ARCHIVED"&&x.Status!="INACTIVE");if(!string.IsNullOrWhiteSpace(term))mq=mq.Where(x=>x.Term==term);if(!string.IsNullOrWhiteSpace(course))mq=mq.Where(x=>x.CourseCode==course);var ms=await mq.OrderBy(x=>x.Term).ThenBy(x=>x.CourseCode).ThenBy(x=>x.Position).ToListAsync(ct);var rows=new List<object>();foreach(var g in groups)foreach(var m in ms.Where(x=>x.Term.Equals(g.Term,StringComparison.OrdinalIgnoreCase)&&x.CourseCode.Equals(g.CourseCode,StringComparison.OrdinalIgnoreCase))){var sub=await db.MilestoneSubmissions.AsNoTracking().FirstOrDefaultAsync(x=>x.GroupId==g.Id&&x.MilestoneId==m.Id,ct);var grade=await db.MilestoneGroupGrades.AsNoTracking().FirstOrDefaultAsync(x=>x.GroupId==g.Id&&x.MilestoneId==m.Id,ct);var memberIds=await db.StudentGroupMembers.Where(x=>x.GroupId==g.Id).Select(x=>x.StudentId).ToListAsync(ct);var scores=await db.MilestoneMemberScores.Where(x=>x.GroupId==g.Id&&x.MilestoneId==m.Id).ToListAsync(ct);rows.Add(new{MilestoneId=m.Id,MilestoneTitle=m.Title,GroupId=g.Id,GroupName=g.Name,g.GroupNo,DeadlineAt=m.DueDate,Submitted=sub!=null,SubmittedAt=sub?.SubmittedAt,Late=sub?.Late,SubmissionStatus=sub?.Status,Graded=grade!=null,Score=grade?.Score,MaxScoreSnapshot=grade?.MaxScoreSnapshot,ContributionsComplete=memberIds.Count>0&&memberIds.All(id=>scores.Any(s=>s.StudentId==id)),GradeComplete=grade!=null&&memberIds.Count>0&&memberIds.All(id=>scores.Any(s=>s.StudentId==id&&s.CalculatedScore!=null))});}return rows;}
 private async Task<object>Overview(string? term,string? course,int limit,CancellationToken ct){if(limit is <1 or >50)throw new BadRequestException("Limit must be between 1 and 50");var q=db.StudentGroups.AsNoTracking().Where(x=>x.SelectedProblemId!=null);if(!string.IsNullOrWhiteSpace(term))q=q.Where(x=>x.Term==term);if(!string.IsNullOrWhiteSpace(course))q=q.Where(x=>x.CourseCode==course);var probs=await q.GroupBy(x=>new{x.SelectedProblem!.Id,x.SelectedProblem.Code,x.SelectedProblem.Title}).Select(g=>new{ProblemId=g.Key.Id,ProblemCode=g.Key.Code,ProblemTitle=g.Key.Title,SelectionCount=g.LongCount()}).OrderByDescending(x=>x.SelectionCount).Take(limit).ToListAsync(ct);var doms=await q.Where(x=>x.SelectedProblem!.DomainId!=null).GroupBy(x=>new{x.SelectedProblem!.Domain!.Id,x.SelectedProblem.Domain.Code,x.SelectedProblem.Domain.Name}).Select(g=>new{DomainId=g.Key.Id,DomainCode=g.Key.Code,DomainName=g.Key.Name,SelectionCount=g.LongCount()}).OrderByDescending(x=>x.SelectionCount).Take(limit).ToListAsync(ct);return new{TotalActiveStudents=await db.Students.LongCountAsync(x=>x.Status=="ACTIVE"&&x.Account.Status=="ACTIVE",ct),TotalActiveMentors=await db.Mentors.LongCountAsync(x=>x.Status=="ACTIVE"&&x.Account.Status=="ACTIVE",ct),TopProblems=probs,TopDomains=doms};}
 private async Task<object>Tv(bool recruit,string? term,string? course,int page,int size,CancellationToken ct){if(page<0)throw new BadRequestException("Page must be greater than or equal to 0");if(size is <1 or >100)throw new BadRequestException("Page size must be between 1 and 100");var active=await db.AcademicTerms.Where(x=>x.Status=="OPEN").OrderByDescending(x=>x.CreatedAt).Select(x=>x.Code).FirstOrDefaultAsync(ct);var q=Groups().Where(x=>active!=null&&x.Status=="ACTIVE"&&x.Term==active);if(!string.IsNullOrWhiteSpace(term)&&!string.Equals(term,active,StringComparison.OrdinalIgnoreCase))q=q.Where(x=>false);if(!string.IsNullOrWhiteSpace(course))q=q.Where(x=>x.CourseCode.ToLower()==course.ToLower());if(recruit)q=q.Where(x=>x.GroupRecruitmentNeeds.Any());else q=q.Where(x=>x.ProjectName!=null&&x.ProjectName!="");var total=await q.LongCountAsync(ct);var groups=await q.Skip(page*size).Take(size).ToListAsync(ct);var content=new List<object>();foreach(var g in groups){var leader=g.LeaderStudent is null?null:new{g.LeaderStudent.Id,g.LeaderStudent.StudentCode,g.LeaderStudent.FullName,Email=g.LeaderStudent.Account.Email};var project=string.IsNullOrWhiteSpace(g.ProjectName)?g.SelectedProblem?.Title??g.Name:g.ProjectName;if(recruit){var positions=g.GroupRecruitmentNeeds.OrderBy(x=>x.Role).Select(x=>new{x.Role,DisplayNameVi=(string?)null,DisplayNameEn=(string?)null,x.Quantity}).ToList();content.Add(new{GroupId=g.Id,g.GroupNo,g.CourseCode,ProjectName=project,InstructorName=g.Instructor?.FullName,Leader=leader,TotalOpenings=positions.Sum(x=>x.Quantity),Positions=positions});}else{var tasks=await db.GroupTasks.Where(x=>x.GroupId==g.Id&&x.ArchivedAt==null).ToListAsync(ct);var done=tasks.LongCount(x=>x.Status=="DONE");content.Add(new{GroupId=g.Id,g.GroupNo,g.CourseCode,ProjectName=project,InstructorName=g.Instructor?.FullName,Leader=leader,ProgressPercent=Percent(done,tasks.Count),CompletedTasks=done,TotalTasks=(long)tasks.Count,InProgressTasks=tasks.LongCount(x=>x.Status is "IN_PROGRESS"or"REVIEW"),OverdueTasks=tasks.LongCount(Overdue),NextDueAt=tasks.Where(x=>x.Status!="DONE"&&x.DueAt>=Now).Min(x=>(DateTime?)x.DueAt)});}}return new{RefreshedAt=Now,ActiveTermCode=active,Content=content,Page=page,Number=page,Size=size,NumberOfElements=content.Count,TotalElements=total,TotalPages=total==0?0:(int)Math.Ceiling(total/(double)size),HasNext=(page+1L)*size<total,HasPrevious=page>0};}
 private static bool Overdue(GroupTask x)=>x.ArchivedAt==null&&x.DueAt!=null&&x.Status!="DONE"&&x.DueAt<Now;private static int Percent(long d,long t)=>t==0?0:(int)Math.Round(d*100d/t,MidpointRounding.AwayFromZero);
}
